def transform(grid):
    h, w = grid.shape
    out = grid.copy()
    seen = np.zeros((h, w), dtype=bool)
    comps = []

    for r in range(h):
        for c in range(w):
            col = grid[r, c]
            if col == 0 or seen[r, c]:
                continue
            q = [(r, c)]
            seen[r, c] = True
            cells = []
            while q:
                rr, cc = q.pop()
                cells.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and grid[nr, nc] == col:
                        seen[nr, nc] = True
                        q.append((nr, nc))
            comps.append((col, cells))

    removals = []
    additions = []

    for col, cells in comps:
        rs = np.array([p[0] for p in cells])
        cs = np.array([p[1] for p in cells])
        r0, r1 = int(rs.min()), int(rs.max())
        c0, c1 = int(cs.min()), int(cs.max())

        foreign = []
        for rr in range(r0, r1 + 1):
            for cc in range(c0, c1 + 1):
                if grid[rr, cc] != 0 and grid[rr, cc] != col:
                    foreign.append((rr, cc, int(grid[rr, cc])))

        if not foreign or len(cells) <= len(foreign):
            continue

        colors = {}
        for rr, cc, fc in foreign:
            colors[fc] = colors.get(fc, 0) + 1
        move_col = max(colors, key=colors.get)
        moving = [(rr, cc) for rr, cc, fc in foreign if fc == move_col]
        if not moving:
            continue

        fr = sum(p[0] for p in moving) / len(moving)
        fc = sum(p[1] for p in moving) / len(moving)
        cr = float(rs.mean())
        cc = float(cs.mean())
        vr, vc = cr - fr, cc - fc
        den = abs(vr) + abs(vc)
        if den == 0:
            den = 1.0

        extremes = {
            "up":    ([(r, c) for r, c in cells if r == r0], -vr / den, r0),
            "down":  ([(r, c) for r, c in cells if r == r1],  vr / den, h - 1 - r1),
            "left":  ([(r, c) for r, c in cells if c == c0], -vc / den, c0),
            "right": ([(r, c) for r, c in cells if c == c1],  vc / den, w - 1 - c1),
        }

        best_dir = None
        best_score = None
        for d, (ecells, align, avail) in extremes.items():
            if avail <= 0:
                continue
            score = align - 0.35 * (len(ecells) - 1)
            if best_score is None or score > best_score:
                best_score = score
                best_dir = d

        if best_dir is None:
            continue

        ecells = extremes[best_dir][0]
        k = min(len(moving), extremes[best_dir][2])
        if k <= 0:
            continue

        removals.extend(moving)

        if best_dir == "up":
            ac = int(round(sum(c for _, c in ecells) / len(ecells)))
            for rr in range(r0 - k, r0):
                additions.append((rr, ac, move_col))
        elif best_dir == "down":
            ac = int(round(sum(c for _, c in ecells) / len(ecells)))
            for rr in range(r1 + 1, r1 + 1 + k):
                additions.append((rr, ac, move_col))
        elif best_dir == "left":
            ar = int(round(sum(r for r, _ in ecells) / len(ecells)))
            for cc2 in range(c0 - k, c0):
                additions.append((ar, cc2, move_col))
        else:
            ar = int(round(sum(r for r, _ in ecells) / len(ecells)))
            for cc2 in range(c1 + 1, c1 + 1 + k):
                additions.append((ar, cc2, move_col))

    for rr, cc in removals:
        out[rr, cc] = 0
    for rr, cc, col in additions:
        if 0 <= rr < h and 0 <= cc < w:
            out[rr, cc] = col

    return out

def transform(grid):
    bg = int(np.bincount(grid.ravel(), minlength=10).argmax())
    counts = np.bincount(grid.ravel(), minlength=10)
    non_bg = [c for c in range(10) if c != bg and counts[c] > 0]
    border = max(non_bg, key=lambda c: counts[c])

    allowed = {border}
    for c in non_bg:
        if counts[c] >= 4:
            allowed.add(c)

    valid = np.zeros(grid.shape, dtype=bool)
    for c in allowed:
        valid |= (grid == c)

    R, C = grid.shape
    seen = np.zeros_like(valid, dtype=bool)
    rects = []

    def edge_ok(a):
        return (
            np.all(a[0, :] == border) or
            np.all(a[-1, :] == border) or
            np.all(a[:, 0] == border) or
            np.all(a[:, -1] == border)
        )

    for sr in range(R):
        for sc in range(C):
            if not valid[sr, sc] or seen[sr, sc]:
                continue

            q = [(sr, sc)]
            seen[sr, sc] = True
            cells = []
            for r, c in q:
                cells.append((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < R and 0 <= nc < C and valid[nr, nc] and not seen[nr, nc]:
                        seen[nr, nc] = True
                        q.append((nr, nc))

            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            submask = valid[r0:r1 + 1, c0:c1 + 1]

            if np.all(submask):
                a = grid[r0:r1 + 1, c0:c1 + 1]
                if a.shape[0] >= 2 and a.shape[1] >= 2 and border in a and edge_ok(a):
                    rects.append((r0, c0, a.copy()))
                continue

            rem = submask.copy()
            while np.any(rem):
                best = None
                h0, w0 = rem.shape
                pref = np.pad(rem.astype(int), ((1, 0), (1, 0))).cumsum(0).cumsum(1)

                for a0 in range(h0):
                    for b0 in range(w0):
                        if not rem[a0, b0]:
                            continue
                        for a1 in range(a0 + 1, h0):
                            for b1 in range(b0 + 1, w0):
                                area = (a1 - a0 + 1) * (b1 - b0 + 1)
                                s = pref[a1 + 1, b1 + 1] - pref[a0, b1 + 1] - pref[a1 + 1, b0] + pref[a0, b0]
                                if s != area:
                                    continue
                                a = grid[r0 + a0:r0 + a1 + 1, c0 + b0:c0 + b1 + 1]
                                if border in a and edge_ok(a):
                                    if best is None or area > best[0]:
                                        best = (area, a0, a1, b0, b1)

                if best is None:
                    break

                _, a0, a1, b0, b1 = best
                rects.append((r0 + a0, c0 + b0, grid[r0 + a0:r0 + a1 + 1, c0 + b0:c0 + b1 + 1].copy()))
                rem[a0:a1 + 1, b0:b1 + 1] = False

    rects.sort(key=lambda x: (x[0], x[1]))
    pieces = [x[2] for x in rects]
    if not pieces:
        return grid.copy()

    area = sum(p.size for p in pieces)
    maxh = max(p.shape[0] for p in pieces)
    maxw = max(p.shape[1] for p in pieces)

    candidates = []
    for h in range(maxh, area + 1):
        if area % h == 0:
            w = area // h
            if w >= maxw:
                candidates.append((h, w))
    candidates.sort(key=lambda hw: (hw[0] > hw[1], abs(hw[1] / hw[0] - 1.6)))

    solution = None

    def fits_boundary(p, y, x, H, W):
        h, w = p.shape
        if y == 0 and not np.all(p[0, :] == border):
            return False
        if y + h == H and not np.all(p[-1, :] == border):
            return False
        if x == 0 and not np.all(p[:, 0] == border):
            return False
        if x + w == W and not np.all(p[:, -1] == border):
            return False
        return True

    for H, W in candidates:
        canvas = np.full((H, W), -1, dtype=int)
        used = [False] * len(pieces)

        def search():
            pos = np.argwhere(canvas == -1)
            if len(pos) == 0:
                return True
            y, x = pos[0]
            for i, p in enumerate(pieces):
                if used[i]:
                    continue
                h, w = p.shape
                if y + h > H or x + w > W:
                    continue
                if np.any(canvas[y:y + h, x:x + w] != -1):
                    continue
                if not fits_boundary(p, y, x, H, W):
                    continue
                used[i] = True
                canvas[y:y + h, x:x + w] = p
                if search():
                    return True
                canvas[y:y + h, x:x + w] = -1
                used[i] = False
            return False

        if search():
            solution = canvas.copy()
            break

    if solution is None:
        return grid.copy()

    H, W = solution.shape
    if H > R or W > C:
        return solution

    out = np.full_like(grid, bg)
    top = (R - H + 1) // 2
    centers = [c + p.shape[1] / 2 for _, c, p in rects]
    left = int(round(sum(centers) / len(centers) - W / 2))
    left = max(0, min(C - W, left))
    out[top:top + H, left:left + W] = solution
    return out

def transform(grid):
    bg = np.bincount(grid.ravel()).argmax()
    vals, cnts = np.unique(grid, return_counts=True)
    counts = {int(v): int(c) for v, c in zip(vals, cnts)}

    non_bg = [c for c in counts if c != bg]
    frame = max(non_bg, key=lambda c: counts[c])

    # The stray marker color is the tiny non-background color; keep the frame
    # and all colors with enough mass to belong to the fragments.
    keep = set(c for c in non_bg if counts[c] > 3)
    keep.add(frame)

    h0, w0 = grid.shape
    mask = np.isin(grid, list(keep))
    seen = np.zeros(grid.shape, dtype=bool)
    pieces = []

    for sr in range(h0):
        for sc in range(w0):
            if not mask[sr, sc] or seen[sr, sc]:
                continue

            stack = [(sr, sc)]
            seen[sr, sc] = True
            cells = []

            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h0 and 0 <= nc < w0 and mask[nr, nc] and not seen[nr, nc]:
                        seen[nr, nc] = True
                        stack.append((nr, nc))

            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            rmin, cmin = min(rs), min(cs)
            rel = [(r - rmin, c - cmin, int(grid[r, c])) for r, c in cells]
            pieces.append({
                "orig": (rmin, cmin),
                "h": max(rs) - rmin + 1,
                "w": max(cs) - cmin + 1,
                "cells": rel,
                "area": len(rel),
            })

    total = sum(p["area"] for p in pieces)
    dims = []
    for h in range(1, h0 + 1):
        if total % h == 0:
            w = total // h
            if w <= w0:
                dims.append((h, w))
    dims.sort(key=lambda x: (abs(x[0] - x[1]), x[0] + x[1]))

    def solve_pack(H, W):
        board = np.full((H, W), -1, dtype=int)
        used = [False] * len(pieces)
        placed = [None] * len(pieces)

        order_cells = [p["cells"] for p in pieces]

        def can_place(i, tr, tc):
            for r, c, v in order_cells[i]:
                rr, cc = tr + r, tc + c
                if rr < 0 or rr >= H or cc < 0 or cc >= W:
                    return False
                if board[rr, cc] != -1:
                    return False
                if (rr == 0 or rr == H - 1 or cc == 0 or cc == W - 1) and v != frame:
                    return False
            return True

        def put(i, tr, tc, val):
            for r, c, v in order_cells[i]:
                board[tr + r, tc + c] = v if val else -1

        def first_empty():
            for r in range(H):
                for c in range(W):
                    if board[r, c] == -1:
                        return r, c
            return None

        def backtrack(n):
            if n == len(pieces):
                return True

            empty = first_empty()
            if empty is None:
                return True
            er, ec = empty

            cand = []
            for i, p in enumerate(pieces):
                if used[i]:
                    continue
                for pr, pc, _ in p["cells"]:
                    tr, tc = er - pr, ec - pc
                    if can_place(i, tr, tc):
                        cand.append((i, tr, tc))

            cand.sort(key=lambda x: -pieces[x[0]]["area"])

            for i, tr, tc in cand:
                used[i] = True
                placed[i] = (tr, tc)
                put(i, tr, tc, True)
                if backtrack(n + 1):
                    return True
                put(i, tr, tc, False)
                placed[i] = None
                used[i] = False

            return False

        if backtrack(0):
            return board.copy(), placed[:]
        return None, None

    best_obj = None
    best_placed = None
    for H, W in dims:
        obj, placed = solve_pack(H, W)
        if obj is not None:
            best_obj = obj
            best_placed = placed
            break

    if best_obj is None:
        return grid.copy()

    H, W = best_obj.shape

    best_score = None
    best_off = (0, 0)
    for tr in range(h0 - H + 1):
        for tc in range(w0 - W + 1):
            score = 0

            for i, p in enumerate(pieces):
                rr, cc = best_placed[i]
                orr, occ = p["orig"]
                score -= abs((tr + rr) - orr) + abs((tc + cc) - occ)

            for r in range(H):
                for c in range(W):
                    if grid[tr + r, tc + c] == best_obj[r, c]:
                        score += 3
                    elif mask[tr + r, tc + c]:
                        score -= 1

            key = (score, tr, tc)
            if best_score is None or key > best_score:
                best_score = key
                best_off = (tr, tc)

    out = np.full(grid.shape, bg, dtype=grid.dtype)
    tr, tc = best_off
    out[tr:tr + H, tc:tc + W] = best_obj
    return out

def transform(grid):
    bg = np.bincount(grid.ravel()).argmax()
    vals, cnts = np.unique(grid, return_counts=True)
    counts = {int(v): int(c) for v, c in zip(vals, cnts)}

    keep = {c for c, n in counts.items() if c != bg and n > 3}
    junk = {c for c in counts if c != bg and c not in keep}

    h, w = grid.shape
    seen = np.zeros((h, w), dtype=bool)
    pieces = []
    anchor = 0

    for r in range(h):
        for c in range(w):
            if seen[r, c] or int(grid[r, c]) not in keep:
                continue

            stack = [(r, c)]
            seen[r, c] = True
            cells = []
            touches_junk = False

            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w:
                        if int(grid[nx, ny]) in junk:
                            touches_junk = True
                        if not seen[nx, ny] and int(grid[nx, ny]) in keep:
                            seen[nx, ny] = True
                            stack.append((nx, ny))

            rs = [x for x, _ in cells]
            cs = [y for _, y in cells]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            arr = np.full((r1 - r0 + 1, c1 - c0 + 1), -1, dtype=int)
            for x, y in cells:
                arr[x - r0, y - c0] = int(grid[x, y])

            if touches_junk:
                anchor = len(pieces)
            pieces.append({"arr": arr, "pos": (r0, c0), "area": len(cells)})

    def variants(a, fixed=False):
        if fixed:
            return [a]
        out = []
        for k in range(4):
            b = np.rot90(a, k)
            for x in (b, np.fliplr(b)):
