    total = sum(p["area"] for p in pieces)
    dims = []
    for hh in range(1, total + 1):
        if total % hh == 0:
            ww = total // hh
            if hh <= h and ww <= w:
                dims.append((hh, ww))
    dims.sort(key=lambda x: (abs((x[1] / x[0]) - (w / h)), max(x), x[0]))

    for oh, ow in dims:
        all_places = []
        by_cell = [[[] for _ in range(ow)] for __ in range(oh)]

        for i, p in enumerate(pieces):
            vs = variants(p["arr"], fixed=(i == anchor))
            placements = []
            for v in vs:
                ph, pw = v.shape
                coords = [(rr, cc, int(v[rr, cc]))
                          for rr in range(ph) for cc in range(pw) if v[rr, cc] != -1]
                for rr in range(oh - ph + 1):
                    for cc in range(ow - pw + 1):
                        cells = tuple((rr + x, cc + y, val) for x, y, val in coords)
                        idx = (i, len(placements), cells, rr, cc)
                        placements.append(idx)
                        for x, y, _ in cells:
                            by_cell[x][y].append(idx)
            all_places.append(placements)

        board = np.full((oh, ow), -1, dtype=int)
        used = [False] * len(pieces)
        chosen = [None] * len(pieces)

        def search(done):
            if done == len(pieces):
                return np.all(board != -1)

            best = None
            best_opts = None
            for rr in range(oh):
                for cc in range(ow):
                    if board[rr, cc] == -1:
                        opts = []
                        for i, _, cells, pr, pc in by_cell[rr][cc]:
                            if used[i]:
                                continue
                            ok = True
                            for x, y, val in cells:
                                if board[x, y] != -1:
                                    ok = False
                                    break
                            if ok:
                                opts.append((i, cells, pr, pc))
                        if best_opts is None or len(opts) < len(best_opts):
                            best = (rr, cc)
                            best_opts = opts
                        if best_opts is not None and len(best_opts) == 0:
                            return False
            if best is None:
                return False

            best_opts.sort(key=lambda z: (-pieces[z[0]]["area"], z[0]))
            for i, cells, pr, pc in best_opts:
                used[i] = True
                chosen[i] = (pr, pc)
                for x, y, val in cells:
                    board[x, y] = val

                if search(done + 1):
                    return True

                for x, y, val in cells:
                    board[x, y] = -1
                chosen[i] = None
                used[i] = False
            return False

