            ar, ac = pieces[anchor]["pos"]
            pr, pc = chosen[anchor]
            top, left = ar - pr, ac - pc

            if 0 <= top and 0 <= left and top + oh <= h and left + ow <= w:
                out = np.full_like(grid, bg)
                out[top:top + oh, left:left + ow] = board
                return out
            return board

    return grid.copy()

