            return mask[::-1, ::-1]
        if op == "cw":
            return np.rot90(mask, -1)
        if op == "ccw":
            return np.rot90(mask, 1)
        return mask

    center_r = (r0 + r1) / 2.0
    center_c = (c0 + c1) / 2.0

    ops = {}
    for color in colors:
        color_comps = comps((g == color) & outside)
        if not color_comps:
            ops[color] = "id"
            continue

        comp = max(color_comps, key=len)
        a, b, d, e = bbox(comp)
        mh, mw = b - a + 1, e - d + 1
        mr, mc = (a + b) / 2.0, (d + e) / 2.0
        dy, dx = mr - center_r, mc - center_c

        if mh > mw:
            op = "r"
        elif mw > mh:
            op = "ccw" if dy < 0 else "r"
        else:
            if dy < 0 and dx > 0:
                op = "ccw"
            elif dy > 0 and dx < 0:
                left_gap = c0 - e
                if left_gap <= 1:
                    op = "cw"
                elif abs(dx) > abs(dy):
                    op = "h"
                else:
                    op = "v"
            elif dy < 0 and dx < 0:
                op = "cw"
            elif abs(dx) > abs(dy):
                op = "h"
            else:
                op = "v"
        ops[color] = op

    for color in colors:
        m = crop == color
        tm = apply_op(m, ops[color])
        if tm.shape == result.shape:
            result[tm] = color

    return result

def transform(grid):
    bg = np.bincount(grid.ravel(), minlength=10).argmax()
    vals = [v for v in np.unique(grid) if v != bg]
    if not vals:
        return grid.copy()
    col = vals[0]

    h, w = grid.shape
    fg = grid == col
    out = np.full_like(grid, bg)

    orth = np.zeros_like(fg, dtype=bool)
    orth[:, 1:] |= fg[:, 1:] & fg[:, :-1]
    orth[:, :-1] |= fg[:, :-1] & fg[:, 1:]
    orth[1:, :] |= fg[1:, :] & fg[:-1, :]
    orth[:-1, :] |= fg[:-1, :] & fg[1:, :]

    diag = np.zeros_like(fg, dtype=bool)
    for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
        a = fg[max(0, dr):h + min(0, dr), max(0, dc):w + min(0, dc)]
        b = diag[max(0, -dr):h - max(0, dr), max(0, -dc):w - max(0, dc)]
        b |= a

    major_row = np.zeros(h, dtype=bool)
    for r in range(h):
        run = 0
        for c in range(w):
            if fg[r, c]:
                run += 1
                if run >= 3:
                    major_row[r] = True
            else:
                run = 0

    major_col = np.zeros(w, dtype=bool)
    for c in range(w):
        run = 0
        for r in range(h):
            if fg[r, c]:
                run += 1
                if run >= 3:
                    major_col[c] = True
            else:
                run = 0

    keep = orth | (fg & ~diag & (major_row[:, None] | major_col[None, :]))
    out[keep] = col

    def row_support(r, a, b):
        for rr in (r - 1, r + 1):
            if 0 <= rr < h:
                if a + 1 < w and fg[rr, a + 1]:
                    return True
                if b - 1 >= 0 and fg[rr, b - 1]:
                    return True
        return False

    def col_support(c, a, b):
        for rr in (a, a + 1, b - 1, b):
            if 0 <= rr < h:
                for cc in range(max(0, c - 2), min(w, c + 3)):
                    if cc != c and fg[rr, cc]:
                        return True
        return False

    for r in range(h):
        xs = np.flatnonzero(out[r] == col)
        if len(xs) < 2:
            continue
        for a, b in zip(xs[:-1], xs[1:]):
            if 1 < b - a <= 4 and row_support(r, a, b):
                out[r, a:b + 1] = col

    for c in range(w):
        ys = np.flatnonzero(out[:, c] == col)
        if len(ys) < 2:
            continue
        for a, b in zip(ys[:-1], ys[1:]):
            if 1 < b - a <= 5 and col_support(c, a, b):
                out[a:b + 1, c] = col

    return out

def transform(grid):
    bg = np.bincount(grid.ravel()).argmax()
    colors = [c for c in np.unique(grid) if c != bg]
    if not colors:
        return grid.copy()
    fg = colors[0]

    out = grid.copy()
    mask = grid == fg
    h, w = grid.shape

    def is_diag_cell(r, c):
        for dr in (-1, 1):
            for dc in (-1, 1):
                if 0 <= r + dr < h and 0 <= c + dc < w and mask[r + dr, c + dc]:
                    return True
        return False

    # Remove cells that are only part of oblique connector/noise strokes.
    keep = np.zeros_like(mask, dtype=bool)
    for r in range(h):
        for c in range(w):
            if not mask[r, c]:
                continue
            horiz = (c > 0 and mask[r, c - 1]) or (c + 1 < w and mask[r, c + 1])
            vert = (r > 0 and mask[r - 1, c]) or (r + 1 < h and mask[r + 1, c])
            if horiz or vert or not is_diag_cell(r, c):
                keep[r, c] = True

    # Keep isolated endpoints that touch an orthogonal line endpoint diagonally:
    # they indicate where a broken horizontal/vertical line should continue.
    endpoints = []
    for r in range(h):
        for c in range(w):
            if not mask[r, c]:
                continue
            n4 = 0
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and mask[rr, cc]:
                    n4 += 1
            if n4 == 1:
                endpoints.append((r, c))

    for r, c in endpoints:
        for rr, cc in endpoints:
            if abs(r - rr) == 1 and abs(c - cc) == 1:
                keep[r, c] = True
                keep[rr, cc] = True

    out[mask & ~keep] = bg

    # Complete straight horizontal runs separated only by background gaps.
    for r in range(h):
        cols = np.where(out[r] == fg)[0]
        if len(cols) < 2:
            continue
        groups = []
        start = prev = cols[0]
        for c in cols[1:]:
            if c == prev + 1:
                prev = c
            else:
                groups.append((start, prev))
                start = prev = c
        groups.append((start, prev))
        for (a1, a2), (b1, b2) in zip(groups, groups[1:]):
            if a2 + 1 < b1 and (a2 - a1 + 1 >= 2 or b2 - b1 + 1 >= 2):
                out[r, a2 + 1:b1] = fg

    # Complete straight vertical runs separated only by background gaps.
    for c in range(w):
        rows = np.where(out[:, c] == fg)[0]
        if len(rows) < 2:
            continue
        groups = []
        start = prev = rows[0]
        for r in rows[1:]:
            if r == prev + 1:
                prev = r
            else:
                groups.append((start, prev))
                start = prev = r
        groups.append((start, prev))
        for (a1, a2), (b1, b2) in zip(groups, groups[1:]):
            if a2 + 1 < b1 and (a2 - a1 + 1 >= 2 or b2 - b1 + 1 >= 2):
                out[a2 + 1:b1, c] = fg

    return out

def transform(grid):
    bg = np.bincount(grid.ravel(), minlength=10).argmax()
    vals = [v for v in np.unique(grid) if v != bg]
    if not vals:
        return grid.copy()
    fg = vals[0]

    h, w = grid.shape
    is_fg = (grid == fg)

    removed = np.zeros_like(is_fg, dtype=bool)
    for r in range(h):
        for c in range(w):
            if not is_fg[r, c]:
                continue
            orth = False
            diag = False
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and is_fg[rr, cc]:
                    orth = True
            for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and is_fg[rr, cc]:
                    diag = True
            if diag and not orth:
                removed[r, c] = True

    keep = is_fg & ~removed
    out = np.full_like(grid, bg)
    out[keep] = fg

    def horiz_run_len(r, c):
        a = c
        while a - 1 >= 0 and keep[r, a - 1]:
            a -= 1
        b = c
        while b + 1 < w and keep[r, b + 1]:
            b += 1
        return b - a + 1

    def vert_run_len(r, c):
        a = r
        while a - 1 >= 0 and keep[a - 1, c]:
            a -= 1
        b = r
        while b + 1 < h and keep[b + 1, c]:
            b += 1
        return b - a + 1

    rem_pts = np.argwhere(removed)

    for r in range(h):
        cols = np.where(keep[r])[0]
        for a, b in zip(cols, cols[1:]):
            gap = b - a - 1
            if gap <= 0 or gap > 5:
                continue
            if horiz_run_len(r, a) < 2 and horiz_run_len(r, b) < 2:
                continue
            ok = False
            for rr, cc in rem_pts:
                if a < cc < b and (abs(rr - r) == abs(cc - a) or abs(rr - r) == abs(cc - b)):
                    ok = True
                    break
            if ok:
                out[r, a:b + 1] = fg

    for c in range(w):
        rows = np.where(keep[:, c])[0]
        for a, b in zip(rows, rows[1:]):
            gap = b - a - 1
            if gap <= 0 or gap > 5:
                continue
            if vert_run_len(a, c) < 2 and vert_run_len(b, c) < 2:
                continue
            ok = False
            for rr, cc in rem_pts:
                if a < rr < b and (abs(cc - c) == abs(rr - a) or abs(cc - c) == abs(rr - b)):
                    ok = True
                    break
            if ok:
                out[a:b + 1, c] = fg

    return out

def transform(grid):
    bg = grid[0, 0]
    out = grid.copy()
    h, w = grid.shape

    # Find bottom-row color bars, which are the instructions.
    bars = []
    c = 0
    while c < w:
        if grid[h - 1, c] != bg:
            color = grid[h - 1, c]
            start = c
            while c < w and grid[h - 1, c] == color:
                c += 1
            bars.append(((start + c - 1) // 2, color))
        else:
            c += 1

    # Locate the regular object columns from all non-background cells above the bar row.
    cols = sorted({j for i in range(h - 1) for j in range(w) if grid[i, j] != bg})
    groups = []
    for x in cols:
        if not groups or x > groups[-1][-1] + 1:
            groups.append([x])
        else:
            groups[-1].append(x)
    centers = [(g[0] + g[-1]) // 2 for g in groups if len(g) >= 3]

    # Locate stamp row blocks.
    rows = sorted({i for i in range(h - 1) for j in range(w) if grid[i, j] != bg})
    row_groups = []
    for r in rows:
        if not row_groups or r > row_groups[-1][-1] + 1:
            row_groups.append([r])
        else:
            row_groups[-1].append(r)
    blocks = [g for g in row_groups if len(g) == 3]

    # Erase instruction bars.
    out[h - 1, :] = bg

    def paint_stamp(top, cx, color):
        for rr, offsets in enumerate(((-1, 0, 1), (-2, -1, 0, 1, 2), (-1, 0, 1))):
            for off in offsets:
                y, x = top + rr, cx + off
                if 0 <= y < h and 0 <= x < w:
                    out[y, x] = color

    def stamp_color(top, cx):
        vals = []
        for rr, offsets in enumerate(((-1, 0, 1), (-2, -1, 0, 1, 2), (-1, 0, 1))):
            for off in offsets:
                y, x = top + rr, cx + off
                if 0 <= y < h and 0 <= x < w and grid[y, x] != bg:
                    vals.append(grid[y, x])
        return vals[0] if vals and all(v == vals[0] for v in vals) else None

    # Each bottom bar names a column. Its color is replaced by the column's visible
    # repeated color; that column is then extended upward to fill the missing cells.
    for cx, key_color in bars:
        if not centers:
            continue
        col = min(range(len(centers)), key=lambda k: abs(centers[k] - cx))
        real_cx = centers[col]

        existing = [stamp_color(b[0], real_cx) for b in blocks]
        existing = [v for v in existing if v is not None and v != key_color]
        replacement = existing[0] if existing else key_color

        for b in blocks:
            top = b[0]
            current = stamp_color(top, real_cx)
            if current == key_color:
                paint_stamp(top, real_cx, replacement)

        seen = any(stamp_color(b[0], real_cx) is not None for b in blocks)
        if seen:
            for b in blocks:
                if stamp_color(b[0], real_cx) is None:
                    paint_stamp(b[0], real_cx, replacement)

    return out

def transform(grid):
    out = grid.copy()
    h, w = out.shape

    vals, counts = np.unique(out, return_counts=True)
    bg = vals[np.argmax(counts)]

    # Bottom-row marker bars.
    markers = []
    c = 0
    while c < w:
        if out[h - 1, c] == bg:
            c += 1
            continue
        color = out[h - 1, c]
        start = c
        while c < w and out[h - 1, c] == color:
            c += 1
        end = c - 1
        markers.append({"color": int(color), "col": (start + end) // 2})
    marker_colors = set(m["color"] for m in markers)
    combined_color = sum(marker_colors)

    # Connected components above the marker row.
    visited = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h - 1):
        for c in range(w):
            color = out[r, c]
            if color == bg or visited[r, c]:
                continue

            stack = [(r, c)]
            visited[r, c] = True
            pts = []
            while stack:
                rr, cc = stack.pop()
                pts.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h - 1 and 0 <= nc < w:
                        if not visited[nr, nc] and out[nr, nc] == color:
                            visited[nr, nc] = True
                            stack.append((nr, nc))

            rs = [p[0] for p in pts]
            cs = [p[1] for p in pts]
            comps.append({
                "pts": pts,
                "color": int(color),
                "minr": min(rs),
                "maxr": max(rs),
                "minc": min(cs),
                "maxc": max(cs),
                "row": (min(rs) + max(rs)) // 2,
                "col": (min(cs) + max(cs)) // 2,
            })

    by_col = {}
    for comp in comps:
        by_col.setdefault(comp["col"], []).append(comp)

    row_centers = sorted(set(comp["row"] for comp in comps))
    diffs = [b - a for a, b in zip(row_centers, row_centers[1:]) if b > a]
    if diffs:
        pitch = min(diffs)
    elif comps:
        pitch = comps[0]["maxr"] - comps[0]["minr"] + 1
    else:
        pitch = 4

    count_from_twos = 0
    for marker in markers:
        if marker["color"] == 2:
            count_from_twos += len(by_col.get(marker["col"], []))
            for comp in by_col.get(marker["col"], []):
                for r, c in comp["pts"]:
                    out[r, c] = combined_color

    for marker in markers:
        if marker["color"] != 3:
            continue
        col_comps = by_col.get(marker["col"], [])
        if not col_comps:
            continue
        template = min(col_comps, key=lambda comp: comp["row"])
        color = template["color"]
        for k in range(1, count_from_twos + 1):
            dr = -pitch * k
            shifted = [(r + dr, c) for r, c in template["pts"]]
            if all(0 <= r < h - 1 for r, c in shifted):
                for r, c in shifted:
                    out[r, c] = color

    out[h - 1, :] = bg
    return out

def transform(grid):
    bg = np.bincount(grid.ravel()).argmax()
    h, w = grid.shape

    best = None
    for col in np.unique(grid):
        if col == bg:
            continue
        rows, cols = np.where(grid == col)
        if len(rows) == 0:
            continue
        for r1 in range(h):
            for r2 in range(r1 + 2, h):
                cs = np.where((grid[r1] == col) & (grid[r2] == col))[0]
                for i in range(len(cs)):
                    c1 = cs[i]
                    for c2 in cs[i + 1:]:
                        if c2 <= c1 + 1:
                            continue
                        if (np.all(grid[r1, c1:c2 + 1] == col) and
                            np.all(grid[r2, c1:c2 + 1] == col) and
                            np.all(grid[r1:r2 + 1, c1] == col) and
                            np.all(grid[r1:r2 + 1, c2] == col)):
                            inside = grid[r1 + 1:r2, c1 + 1:c2]
                            if inside.size and len(np.unique(inside)) == 1:
                                area = (r2 - r1 + 1) * (c2 - c1 + 1)
                                if best is None or area > best[0]:
                                    best = (area, r1, r2, c1, c2, col, inside[0, 0])

    _, r1, r2, c1, c2, frame, fill = best
    out = np.full((r2 - r1 - 1, c2 - c1 - 1), fill, dtype=grid.dtype)

    blocked = np.zeros_like(grid, dtype=bool)
    blocked[r1:r2 + 1, c1:c2 + 1] = True
    vis = (grid != bg) & (~blocked)

    def color_at(points, fixed, pos, horizontal=True):
        vals = []
        for rr, cc, v in points:
            if (horizontal and rr == fixed) or ((not horizontal) and cc == fixed):
                vals.append((cc if horizontal else rr, v))
        if not vals:
            return None
        if len(set(v for _, v in vals)) == 1:
            return vals[0][1]

        for p in range(1, 9):
            m = {}
            ok = True
            for x, v in vals:
                k = x % p
                if k in m and m[k] != v:
                    ok = False
                    break
                m[k] = v
            if ok and pos % p in m:
                return m[pos % p]

        vals.sort(key=lambda x: abs(x[0] - pos))
        return vals[0][1]

    groups = []
    for col in np.unique(grid[vis]):
        pts = [(int(r), int(c), int(grid[r, c])) for r, c in zip(*np.where(vis & (grid == col)))]
        if pts:
            groups.append(pts)

    seen = np.zeros_like(grid, dtype=bool)
    for sr, sc in zip(*np.where(vis)):
        if seen[sr, sc]:
            continue
        stack = [(int(sr), int(sc))]
        seen[sr, sc] = True
        pts = []
        while stack:
            rr, cc = stack.pop()
            pts.append((rr, cc, int(grid[rr, cc])))
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = rr + dr, cc + dc
                if 0 <= nr < h and 0 <= nc < w and vis[nr, nc] and not seen[nr, nc]:
                    seen[nr, nc] = True
                    stack.append((nr, nc))
        groups.append(pts)

    for pts in groups:
        rs = [p[0] for p in pts]
        cs = [p[1] for p in pts]
        gr1, gr2, gc1, gc2 = min(rs), max(rs), min(cs), max(cs)

        row_counts = {}
        col_counts = {}
        for rr, cc, _ in pts:
            row_counts[rr] = row_counts.get(rr, 0) + 1
            col_counts[cc] = col_counts.get(cc, 0) + 1

        for rr, cnt in row_counts.items():
            if cnt < 2 or not (r1 < rr < r2):
                continue
            for cc in range(max(c1 + 1, gc1), min(c2, gc2 + 1)):
                v = color_at(pts, rr, cc, True)
                if v is not None:
                    out[rr - r1 - 1, cc - c1 - 1] = v

        for cc, cnt in col_counts.items():
            if cnt < 2 or not (c1 < cc < c2):
                continue
            for rr in range(max(r1 + 1, gr1), min(r2, gr2 + 1)):
                v = color_at(pts, cc, rr, False)
                if v is not None:
                    out[rr - r1 - 1, cc - c1 - 1] = v

    return out

